"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4: how reliable the sound detector's labels are on dev, for the fairness prompts of the Gemini readers
(docs/iterations.md, 2026-11-19; approved by the author). Analysis of dev only, no API.

What a reader sees: every detected sound before the decision point, as "detected sound: <name>, a to b (confidence
c)" (p1v4_situation.build). Here, for each detector class and confidence band:
- precision: of the detections shown in dev situation texts, the share that were really there: a source clip of the
  same class overlaps the detection, with 0.5 s slack on both sides. A detection repeated at several points of the same
  unit version counts once (same class, start to 0.1 s and confidence to 0.01).
- misses: of the real sound clips of each class that start before a decision point of their unit version, the share
  that no shown detection of the same class overlaps (same slack).
Bands as the trust curves: below 0.5, 0.5 to 0.7, 0.7 to 0.9, 0.9 to 0.99, 0.99 or more.
Outputs: results/main_v04/detector_precision_dev.json and configs/b2_detector_reliability_v1.txt, the text that
the "prec" prompt variant of scripts/p1v4_api.py adds (fixed before any Gemini call with it).
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_detector_precision.py
"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_situation as SIT  # noqa: E402

SLACK_S = 0.5
EDGES = [0.0, 0.5, 0.7, 0.9, 0.99, 1.0 + 1e-9]
BANDS = ["below 0.50", "0.50 to 0.70", "0.70 to 0.90", "0.90 to 0.99", "0.99 or more"]
ORDER = ["phone", "doorbell", "knock", "footsteps", "door", "cabinet", "decoy"]
TEXT_OUT = "configs/b2_detector_reliability_v1.txt"


def band(c):
    return next(b for lo, hi, b in zip(EDGES[:-1], EDGES[1:], BANDS) if lo <= c < hi)


def overlaps(src, cls, a, b):
    return src["kind"] == "clip" and src.get("cls") == cls and src["start"] < b + SLACK_S and src["end"] > a - SLACK_S


def main():
    rows = D.load_rows("dev")
    ctx = C.Context("dev")
    prec = {c: {b: [0, 0] for b in BANDS} for c in ORDER}          # [right, shown]
    miss = {c: [0, 0] for c in ORDER}                               # [missed, real]
    per_point = {c: {b: [0, 0] for b in BANDS} for c in ORDER}      # every shown detection, repeats included
    for r in rows:
        seen, shown = set(), []
        for p in r["points"]:
            for cls, s0, s1, peak in ctx.point(r, p["k"])[3]:
                if s0 >= p["t"]:
                    continue
                s1 = min(s1, p["t"])
                right = any(overlaps(s, cls, s0, s1) for s in r["sources"])
                per_point[cls][band(peak)][0] += right
                per_point[cls][band(peak)][1] += 1
                key = (cls, round(s0, 1), round(peak, 2))
                if key not in seen:
                    seen.add(key)
                    prec[cls][band(peak)][0] += right
                    prec[cls][band(peak)][1] += 1
                    shown.append((cls, s0, s1))
        last_t = max(p["t"] for p in r["points"])
        for s in r["sources"]:
            if s["kind"] == "clip" and s.get("cls") in ORDER and s["start"] < last_t:
                found = any(cls == s["cls"] and overlaps(s, cls, a, b) for cls, a, b in shown)
                miss[s["cls"]][0] += not found
                miss[s["cls"]][1] += 1
    res = {"slack_s": SLACK_S, "bands": BANDS, "precision": prec, "misses": miss, "per_point_precision": per_point}
    json.dump(res, open("results/main_v04/detector_precision_dev.json", "w"), indent=1)

    lines = ["How reliable the detected sounds are, measured on held-out recordings made the same way as these cases "
             "(for each detected sound and confidence range: the share of detections that were really there, and "
             "how many detections that share is based on):"]
    for c in ORDER:
        cells = []
        for b in BANDS:
            right, n = prec[c][b]
            cells.append(f"{b}: no cases" if n == 0 else f"{b}: {100 * right / n:.0f}% right (of {n})")
        lines.append(f"- {SIT.SOUND_NAMES[c]}: " + "; ".join(cells))
    lines.append("The detector also misses real sounds. Share of real sounds that got no detection at all:")
    lines.append("- " + "; ".join(f"{SIT.SOUND_NAMES[c]}: {100 * m / n:.0f}% (of {n})" if n else
                                  f"{SIT.SOUND_NAMES[c]}: no cases" for c, (m, n) in miss.items()))
    text = "\n".join(lines)
    open(TEXT_OUT, "w", encoding="utf-8", newline="\n").write(text + "\n")
    print(text)
    print("\nper point (repeats included), phone/doorbell/knock:")
    for c in ("phone", "doorbell", "knock"):
        print(c, {b: f"{x[0]}/{x[1]}" for b, x in per_point[c].items()})


if __name__ == "__main__":
    main()
